const imgs = [...document.querySelectorAll('svg image')];
const info = imgs.map(i => ({href: (i.getAttribute('href')||'').slice(0,30), nw: i.naturalWidth || 0, w: i.getAttribute('width'), h: i.getAttribute('height')}));
return {title: document.title, svgEls: document.querySelectorAll('svg *').length, images: info.slice(0,12), pngIcons: imgs.filter(i=>(i.getAttribute('href')||'').startsWith('data:image/png')).length, svgIcons: imgs.filter(i=>(i.getAttribute('href')||'').startsWith('data:image/svg')).length};
